            "text": "A AAMAR – Associação Amar e Renascer é uma organização de sociedade civil, sem fins lucrativos, atuando como Comunidade Terapêutica, voltada para a prevenção, tratamento, desintoxicação, recuperação e ressocialização de dependentes de álcool e de outras drogas.",
