            "_type": "span",
            "_key": "ki",
            "text": "Em 10 de fevereiro de 2018, foi inaugurada a AAMAR Santana do Paraíso/MG (Foto abaixo), com a capacidade para o tratamento de 15 pessoas, exclusivamente mulheres, e para isso conta hoje com uma equipe de 6 funcionários e de voluntários dedicados em áreas multidisciplinares.",
