          {
            "_type": "span",
            "_key": "k1u2",
            "text": "Antes de iniciar a análise SWOT, é importante estar preparado. Isso inclui ter uma compreensão clara de seus objetivos de carreira, ser específico, estar disposto a ser honesto consigo mesmo, e, se possível, coletar feedback de outras pessoas. Os seguintes passos são fundamentais para construção de uma análise SWOT e de um Plano de Ação:",
            "marks": []
          }
